 updateStick(){if(!this.pointer)return;const p=this.pointer;if(p.mouse){p.dx=p.current.x-(this.r.x-this.r.camera.x);p.dy=p.current.y-(this.r.y-this.r.camera.y)}else{p.dx=p.current.x-p.start.x;p.dy=p.current.y-p.start.y}}
 resize(){if(!this.canvas)return;const b=this.g.modeRoot.getBoundingClientRect(),scale=b.width<700?1.6:2;this.r.viewW=Math.max(220,Math.round(b.width/scale));this.r.viewH=Math.max(250,Math.round(b.height/scale));this.canvas.width=this.r.viewW;this.canvas.height=this.r.viewH;this.r.vision=clamp(Math.min(this.r.viewW*.62,this.r.viewH*.51),145,245);this.ctx.imageSmoothingEnabled=false;this.clearInput()}
 onKey(e){if(!this.active)return;if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(/^Digit[1-4]$/.test(e.code)||/^[1-4]$/.test(key)){this.select(+e.code.slice(-1)||+key);return}if(e.repeat&&['escape','e'].includes(key))return;if(key==='escape'){e.preventDefault();if(!this.g.modal.open)this.paused?this.resume('menu'):this.pause('menu');return}if(key==='e'){this.openChest();return}this.keys.add(key)}
 clearInput(){this.keys.clear();this.pointer=null}
